using FreshFoundation;
using System.Text.Json;
using System.Drawing.Imaging;
namespace RiseWorkshopDesktop;
internal static class R10ReviewSmoke
{
    internal static void Run(string folder)
    {
        Directory.CreateDirectory(folder);var results=new List<object>();int failed=0;void Test(string name,Action check){try{check();results.Add(new{name,status="PASS"});}catch(Exception e){failed++;results.Add(new{name,status="FAIL",error=e.GetType().Name+": "+e.Message});}}
        foreach(string language in new[]{"en","zh-CN"}){UiLanguage.Set(language,false);Test(language+" actual virtual level zero control",()=>{var planner=new BuildPlanner(R10Checks.Catalog()){ShowCandidates=true};using var form=new BuildPieceForm(planner,BuildPosition.Talisman);form.CreateControl();if(!form.SmokeLevelZero())throw new Exception("Nonempty skill retained zero level");});}
        foreach(string language in new[]{"en","zh-CN"}){UiLanguage.Set(language,false);foreach(var position in new[]{BuildPosition.Weapon,BuildPosition.Talisman})Test(language+" persistent search and slot labels "+position,()=>{var planner=new BuildPlanner(R10Checks.Catalog()){ShowCandidates=true};using var form=new BuildPieceForm(planner,position){Size=new(840,620),ShowInTaskbar=false,Opacity=0};form.Show();Application.DoEvents();if(!form.SmokeFilterRetention())throw new Exception("Decoration filter cleared during rebuild");Render(form,language+"-filter-"+position+".png");form.Close();});Test(language+" piece contribution and confirmed virtual detail",()=>{var planner=new BuildPlanner(R10Checks.Catalog()){ShowCandidates=true};var piece=new PlannedPiece(BuildPosition.Head,1001,[20,0,0]);string text=BuildPresentation.Piece(planner,piece);if(!text.Contains("ID 10: 3")||!text.Contains(language=="en"?"THIS PIECE":"本单件贡献"))throw new Exception("Missing decorated-piece contribution");var talisman=new PlannedPiece(BuildPosition.Talisman,null,[20,0,0],new([new(10,2),new(0,0)],[2,0,0]));planner.Confirm(talisman);text=BuildPresentation.Piece(planner,planner.Piece(BuildPosition.Talisman)!);if(!text.Contains("ID 10 / ")||!text.Contains("2 / 0 / 0")||text.Contains("No matching catalog"))throw new Exception("Confirmed virtual talisman omitted its own fields");planner.ShowCandidates=false;text=BuildPresentation.Piece(planner,piece);if(text.Contains("SYNTHETIC")||text.Contains("合成"))throw new Exception("Hidden candidate name leaked");});using var build=new BuildForm(R10Checks.Catalog()){Size=new(900,600),ShowInTaskbar=false,Opacity=0};build.Show();Application.DoEvents();Render(build,language+"-build-minimum.png");build.Close();}
        Test("local catalog callback retained by actual Build factory",()=>{string local=Path.Combine(folder,"catalog-local");Directory.CreateDirectory(local);var data=new GameCatalogFile(1,[new(GameCatalogKind.Weapon,777001,new(){["en"]="SYNTHETIC LOCAL ONLY"},"GreatSword",Origin:new("synthetic","synthetic"))]);File.WriteAllText(Path.Combine(local,"catalog.json"),JsonSerializer.Serialize(data));using var workshop=new WorkshopForm();string first=Path.Combine(folder,"catalog-first");Directory.CreateDirectory(first);File.WriteAllText(Path.Combine(first,"catalog.json"),JsonSerializer.Serialize(new GameCatalogFile(1,[new(GameCatalogKind.Weapon,777000,new(){["en"]="SYNTHETIC FIRST ONLY"},"GreatSword",Origin:new("synthetic","synthetic"))])));using(var initial=workshop.CreateCatalogBrowser())initial.LoadLocalCatalog(first);using(var initialBuild=workshop.CreateBuildWindow())if(!initialBuild.SmokeContainsWeapon(777000))throw new Exception("First local catalog lost");using(var browser=workshop.CreateCatalogBrowser())browser.LoadLocalCatalog(local);using var build=workshop.CreateBuildWindow();if(!build.SmokeContainsWeapon(777001)||build.SmokeContainsWeapon(777000))throw new Exception("Local catalog lost at Build entry");try{using var browser=workshop.CreateCatalogBrowser();browser.LoadLocalCatalog(Path.Combine(folder,"missing"));}catch(IOException){}using var after=workshop.CreateBuildWindow();if(!after.SmokeContainsWeapon(777001))throw new Exception("Failed load replaced selection");});
        void Render(Form form,string name){using var image=new Bitmap(form.Width,form.Height);form.DrawToBitmap(image,new(Point.Empty,form.Size));image.Save(Path.Combine(folder,name),ImageFormat.Png);}
        File.WriteAllText(Path.Combine(folder,"review-results.json"),JsonSerializer.Serialize(new{atUtc=DateTimeOffset.UtcNow,failed,results},new JsonSerializerOptions{WriteIndented=true}));Environment.ExitCode=failed==0?0:1;
    }
}
